import{_ as s,C as t,o as r,c as o,E as a,a2 as d}from"./chunks/framework.VWKgVqrc.js";const g=JSON.parse('{"title":"Before Reading a Collusion Score, Ask Who Survived the Label Rule","description":"","frontmatter":{"title":"Before Reading a Collusion Score, Ask Who Survived the Label Rule","article_type":"technical-analysis","edition":"research-center","research_question":"严格选择标签依据哪些证据保留或排除样本，这会怎样限制监测分数的解读？","summary":"Strict labels combine target votes with private stance. Mixed signals are excluded and missing stance is nonpositive; score interpretation needs evidence completeness and the retained population.","sources":"arXiv:2611.10620v1; pinned collusion-probe-pitfalls source and stored author results; corrected archive metadata","date":"2026-11-12","column":"open-source-engineering","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261112-006","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-12-sig-20261112-006-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-11-12-sig-20261112-006.md","filePath":"en/engineering/2026-11-12-sig-20261112-006.md","lastUpdated":null}'),l={name:"en/engineering/2026-11-12-sig-20261112-006.md"};function c(h,e,p,u,m,b){const n=t("ArticleCover"),i=t("ArticleTableScroll");return r(),o("div",null,[a(n,{image:"/assets/covers/daily-2026-11-12-sig-20261112-006-cover.png",kicker:"Research",title:"Before Reading a Collusion Score, Ask Who Survived the Label Rule",summary:"Strict labels combine target votes with private stance. Mixed signals are excluded and missing stance is nonpositive; score interpretation needs evidence completeness and the retained population.",version:"2026-11-12",languageHref:"/zh/engineering/2026-11-12-sig-20261112-006",languageLabel:"中文"}),a(i,{language:"en"}),e[0]||(e[0]=d('<h1 id="before-reading-a-collusion-score-ask-who-survived-the-label-rule" tabindex="-1">Before Reading a Collusion Score, Ask Who Survived the Label Rule <a class="header-anchor" href="#before-reading-a-collusion-score-ask-who-survived-the-label-rule" aria-label="Permalink to &quot;Before Reading a Collusion Score, Ask Who Survived the Label Rule&quot;">​</a></h1><p>A case casts the target vote but has no readable private-stance record. In our synthetic-input check of pinned source, it receives no strict “joining” label: it is excluded. With the same missing stance and no target vote, the function returns a negative label. Before any score is interpreted, evidence availability and combination rules have already selected the comparison population.</p><p>This is not evidence that a monitor fails. The narrower judgment is that interpreting multi-agent collusion monitoring requires knowing what evidence labels need, which cases are excluded and how missing evidence is handled. Otherwise, even a valid ranking score may answer a narrower question than the reader assumes.</p><h2 id="strict-labels-define-the-population-first" tabindex="-1">Strict labels define the population first <a class="header-anchor" href="#strict-labels-define-the-population-first" aria-label="Permalink to &quot;Strict labels define the population first&quot;">​</a></h2><p>The inspected research considers instruction cues, decision cues and monitoring scores. Its strict choice-label function does more than ask whether an agent cast a target vote. It also reads private-message stance signals and combines the two judgments. In the pinned source, strict mode retains both-positive cases as true and both-nonpositive cases as false; disagreements become null and leave that strict comparison.[1][2]</p><p>Null is not another negative label: it means exclusion. Replacing “vote or private agreement” with “both” changes both the positive criterion and the retained set. Strict mode can improve label agreement, but a score based on it concerns this selected population. That is an interpretation of the measurement mechanism, not a statistical finding from recomputed author data.</p><p>The inspected implementation uses scenario-group cross-fitting and rounds 1–4. Source code establishes these intended operations, not correctness of every real episode annotation or recomputation of episode contents and outputs.[2]</p><h2 id="what-six-synthetic-cases-establish" tabindex="-1">What six synthetic cases establish <a class="header-anchor" href="#what-six-synthetic-cases-establish" aria-label="Permalink to &quot;What six synthetic cases establish&quot;">​</a></h2><p>The same-day research analysis extracted and executed the strict choice-label and option-relabeling functions at commit <code>d4adba6120246098b7f54dddd6af0782b4a47662</code>. Inputs were synthetic configuration and stance files, not the paper&#39;s dataset. NumPy was unavailable. Only for the simple scalar lists in these fixtures, Python&#39;s standard-library mean replaced its mean call; array operations, training and model inference were not emulated.[3]</p><table tabindex="0"><thead><tr><th>Synthetic condition</th><th>Any-positive label</th><th>Strict agreement label</th></tr></thead><tbody><tr><td>Positive target vote and positive private stance</td><td>True</td><td>True</td></tr><tr><td>Target vote only</td><td>True</td><td>Null, excluded</td></tr><tr><td>Private stance only</td><td>True</td><td>Null, excluded</td></tr><tr><td>Both nonpositive</td><td>False</td><td>False</td></tr><tr><td>Missing private stance, positive target vote</td><td>True</td><td>Null, excluded</td></tr><tr><td>Missing private stance, nonpositive target vote</td><td>False</td><td>False</td></tr></tbody></table><p>The table reports an internal isolated-function experiment, not independent reproduction. Strict labeling retains one true and two false cases and excludes three of these six fixtures. These counts describe deliberately constructed cases; they are not estimates of real-data coverage or missingness.[3]</p><p>The tested function treats missing private stance as nonpositive. Consequently, the last case receives the same label as a case with two observed nonpositive signals, despite a different evidence state. It should not be described without qualification as an observed refusal. Removing the entire stance file also turns the formerly both-positive case into an exclusion, while the formerly private-only case becomes false. This exposes the function&#39;s evidence dependency, not the prevalence of missingness in released data.[3]</p><p>The same isolated experiment checked four option-label combinations and nonmatching text controls. The pinned generator rewrites canonical option references to current fair and target labels, and the four fixture outputs behaved as specified. This establishes the tested substitutions, not semantic correctness of every real episode&#39;s options and stance labels.[3][4]</p><h2 id="ranking-alarms-and-observation-time-are-different-quantities" tabindex="-1">Ranking, alarms and observation time are different quantities <a class="header-anchor" href="#ranking-alarms-and-observation-time-are-different-quantities" aria-label="Permalink to &quot;Ranking, alarms and observation time are different quantities&quot;">​</a></h2><p>On the committee hard-negative comparison, authors report agent AUROC falling from 1.00 to 0.61 when briefing and private context are removed, while a same-prompt decision probe retains 0.73. AUROC measures ranking discrimination. This intervention also changes the input distribution, so it does not cleanly identify whether a score reflects a goal or contextual cues.[1]</p><p>High ranking performance does not ensure a deployed threshold&#39;s false-alarm rate. Authors report committee-to-code-review and reverse-transfer AUROC of 0.994 and 0.966, while thresholds set for 1% source false alarms yield 2.5% and 4.0% on target data. An unretrained probe scores 0.50 on the emergent-collusion episodes used. These remain the authors&#39; experimental results, not measurements from our function checks.[1]</p><p>The inspected stored author results give a more direct example. In the no-brief experiment, the instruction probe has AUROC 0.99468 against the honest adapter while run-level false alarms on controls are 0.21212 and 0.28283. The decision probe flags 14% of implanted runs with no observed control alarms. Agent-level ranking and run-level alarms use different units and cannot substitute for one another. Zero observed alarms cannot be expanded into zero false-alarm risk.[5]</p><p>Observation time also changes the question. The authors&#39; post-vote rule reaches AUROC 0.990 on successful attempts, but before voting it has no outcome to read. The main evaluation instead scores all attempts before the vote. Retrospective screening and prospective detection have different information and population conditions. Our label-mechanism probe neither recomputes these numbers nor supplies an empirical correction or refutation.[1]</p><p>Our engineering interpretation is to report target behavior, required label evidence, retained and excluded counts, scoring time, observation unit and actual threshold errors together. Those facts determine which decisions a reader can reasonably base on the score.</p><h2 id="label-purity-has-a-defensible-scope" tabindex="-1">Label purity has a defensible scope <a class="header-anchor" href="#label-purity-has-a-defensible-scope" aria-label="Permalink to &quot;Label purity has a defensible scope&quot;">​</a></h2><p>Strict labels are not inherently wrong. Researchers can deliberately exclude mixed signals to compare participants and nonparticipants with consistent evidence. If actual episode stance files are complete, the missing-evidence branch may have no effect on the original results. This synthetic experiment does not establish a defect in the intended complete-data use.</p><p>The corresponding cost is that coverage needs to be visible: excluded mixed behavior may still occur at deployment. We did not measure its real-world prevalence, trained evasion or spontaneous secret collusion. Labels depend on the generator and stance model; humans did not review every audit-flagged run. These limits continue to constrain interpretation.[1][2]</p><p>Archive metadata identifies version 1.2 as corrected, including concealed-message analyses missed in 1.1. Preregistration Amendment 7 records option-label issues affecting 572/1000 main attempts, with adapters not retrained. These are version and author-amendment records. Corrected raw episodes and activations were not obtained here; bootstrap analyses and complete outputs were not recomputed, and implanted adapter weights are withheld. Archive identity and a DOI cannot fill these empirical gaps.[1][4][6]</p><h2 id="evidence-and-sources" tabindex="-1">Evidence and sources <a class="header-anchor" href="#evidence-and-sources" aria-label="Permalink to &quot;Evidence and sources&quot;">​</a></h2><p>Public primary-source facts describe processing visible in pinned code and version records. Our observations identify inspected code paths; internal experimental evidence covers selected functions on synthetic inputs. All model-performance statistics remain source-reported rather than independent evidence. We trained no adapter, ran no monitoring model and recomputed no paper score. Citation is not endorsement, peer review is not proof, and self-reported evidence is not independent evidence. Publication or archiving does not establish general collusion-detection efficacy, and implementation success does not establish general validity.</p><ol><li>Mainul Hasan Mohsin and Mohammad Shahidur Rahman, <em>What Do Collusion Probes Read? Three Pitfalls in Evaluating Multi-Agent Collusion Monitors</em>, preprint arXiv:2611.10620v1, experimental comparisons, timing and transfer, snapshot read on 2026-11-12. <a href="https://arxiv.org/html/2611.10620v1" target="_blank" rel="noreferrer">Paper</a>.</li><li>Project authors, pinned <code>instruction_tests.py</code>, strict choice labels and scenario-group cross-fitting, commit <code>d4adba6120246098b7f54dddd6af0782b4a47662</code>, snapshot read on 2026-11-12. <a href="https://github.com/mainul3195/collusion-probe-pitfalls/blob/d4adba6120246098b7f54dddd6af0782b4a47662/code/instruction_tests.py" target="_blank" rel="noreferrer">Label source</a>.</li><li>Research Center, <a href="/joinwell52/assets/evidence/2026-11-12-sig-20261112-006/006-experiment.json">internal isolated-function experimental record, 2026-11-12</a>: six synthetic chooser cases, four option permutations and the disclosed scalar mean adapter. Neither dataset reproduction nor model evaluation.</li><li>Project authors, pinned generator and preregistration Amendment 7, snapshot read on 2026-11-12. <a href="https://github.com/mainul3195/collusion-probe-pitfalls/blob/d4adba6120246098b7f54dddd6af0782b4a47662/code/gen_e2v2.py" target="_blank" rel="noreferrer">Generator</a>; <a href="https://github.com/mainul3195/collusion-probe-pitfalls/tree/d4adba6120246098b7f54dddd6af0782b4a47662/prereg" target="_blank" rel="noreferrer">preregistration records</a>.</li><li>Project authors, stored no-brief experimental results at the pinned revision, inspected without rerunning. <a href="https://raw.githubusercontent.com/mainul3195/collusion-probe-pitfalls/d4adba6120246098b7f54dddd6af0782b4a47662/results/paper1/nobrief/main.json" target="_blank" rel="noreferrer">Author results</a>.</li><li>Zenodo, author archive description for corrected version 1.2, metadata read on 2026-11-12. <a href="https://doi.org/10.5281/zenodo.23636508" target="_blank" rel="noreferrer">Archive identity</a>.</li></ol><h2 id="the-missing-next-evidence-is-episode-evidence" tabindex="-1">The missing next evidence is episode evidence <a class="header-anchor" href="#the-missing-next-evidence-is-episode-evidence" aria-label="Permalink to &quot;The missing next evidence is episode evidence&quot;">​</a></h2><p>The discriminating next evidence would independently examine corrected raw episodes and their labels and exclusions: does missingness actually occur, how common are mixed cases, and do independent annotators agree with private-stance judgments? Only then can further work test whether thresholds retain expected false alarms on realistic changing honest traffic, and whether no-brief separation reflects goals or training-style residue.</p><p>This study answers how selected functions choose the comparison population. It does not establish the prevalence of those populations in actual data or whether general collusion can be detected. Reporting who survives the label rule gives a score a defined object of interpretation.</p>',29))])}const v=s(l,[["render",c]]);export{g as __pageData,v as default};
